#include <bits/stdc++.h>
using namespace std;

struct InputData {
    long long modulus;
    int total_n, total_m;
    bool read() {
        return !!(cin >> total_n >> total_m >> modulus);
    }
};

struct ResultData: InputData {
    long long answer;
    void output() {
        cout << answer << "\n";
    }
};

namespace Solver {
    struct Solution: ResultData {
        long long power(long long base, long long exp) {
            long long res = 1;
            while (exp > 0) {
                if (exp & 1) res = res * base % modulus;
                base = base * base % modulus;
                exp >>= 1;
            }
            return res;
        }

        long long inverse(long long x) {
            return power(x, modulus - 2);
        }

        long long comb[502][502];

        pair<long long, long long> sequence[503];
        pair<long long, long long> dp[503][503];

        void compute() {
            for (int i = 0; i <= total_n; ++i) {
                for (int j = 0; j <= total_n; ++j) {
                    if (i == 0 || j == 0) comb[i][j] = 1;
                    else comb[i][j] = (comb[i - 1][j] + comb[i][j - 1]) % modulus;
                }
            }

            fill_n(sequence, total_m + 1, make_pair(0, 0));
            sequence[0] = {1, 0};
            for (int i = 1; i <= total_m; ++i) {
                for (int j = 0; j < i; ++j) {
                    pair<long long, long long> current;
                    current.first = sequence[j].first * sequence[i - 1 - j].first % modulus;
                    current.second = (sequence[j].second * sequence[i - 1 - j].first + sequence[j].first * sequence[i - 1 - j].second) % modulus;
                    current.second = (current.second * (i + 1) + (ss(j) + ss(i - 1 - j)) * current.first) % modulus;
                    current.first = current.first * (i + 1) % modulus;
                    current.first = current.first * comb[j][i - 1 - j] % modulus;
                    current.second = current.second * comb[j][i - 1 - j] % modulus;
                    sequence[i].first = (sequence[i].first + current.first) % modulus;
                    sequence[i].second = (sequence[i].second + current.second) % modulus;
                }
            }

            memset(dp, 0, sizeof dp);
            dp[0][0] = {1, 0};
            for (int i = 0; i <= total_n + 1; ++i) {
                for (int j = 0; j <= total_m; ++j) {
                    for (int k = 0; k <= min(total_n - i, total_m - j); ++k) {
                        pair<long long, long long> current;
                        current.first = sequence[k].first * dp[i][j].first % modulus;
                        current.second = (sequence[k].second * dp[i][j].first + sequence[k].first * dp[i][j].second) % modulus;
                        current.first = current.first * comb[j][k] % modulus;
                        current.second = current.second * comb[j][k] % modulus;
                        dp[i + k + 1][j + k].first = (dp[i + k + 1][j + k].first + current.first) % modulus;
                        dp[i + k + 1][j + k].second = (dp[i + k + 1][j + k].second + current.second) % modulus;
                    }
                }
            }
            answer = dp[total_n + 1][total_m].second;
        }
        void reset() {
            *this = Solution();
        }
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Solver::Solution sol;
    if (getenv("SG")) {
        freopen("problem.in", "r", stdin);
        while (sol.read()) {
            sol.compute();
            sol.output();
            sol.reset();
        }
    } else {
        sol.read();
        sol.compute();
        sol.output();
    }
    return 0;
}
